function screenReport(){const ratio=window.devicePixelRatio||1;return {screenWidth:Math.round(screen.width*ratio),screenHeight:Math.round(screen.height*ratio),viewportWidth:innerWidth,viewportHeight:innerHeight,pixelRatio:ratio}}
async function reportScreen(){if(previewMode||!me?.device)return;try{await api('/api/device/screen',{method:'POST',body:JSON.stringify(screenReport())})}catch{}}
const previewMode=new URLSearchParams(location.search).has('preview');if(previewMode)document.documentElement.classList.add('preview-mode');
setInterval(()=>{$('#clock').textContent=new Intl.DateTimeFormat(undefined,matchMedia('(max-width:760px)').matches?{weekday:'short',month:'short',day:'numeric',year:'numeric'}:{weekday:'short',month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date()).toUpperCase();const period=routinePeriod();if(dashboard&&period!==shownRoutinePeriod)renderTasks();applyDim()},1000);setInterval(()=>{if(new Date().toLocaleDateString('en-CA')!==shownDay)refreshLive()},60000);setInterval(refreshLive,300000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshLive()});setInterval(checkDeployment,30000);setInterval(()=>reportScreen(),60000);window.addEventListener('resize',()=>{reportScreen();sizeScreenPreviews()});if(window.ResizeObserver)new ResizeObserver(()=>sizeScreenPreviews()).observe(document.body);window.addEventListener('hashchange',()=>openView(location.hash.slice(1)));if('serviceWorker'in navigator)navigator.serviceWorker.register('/service-worker.js');load().then(()=>{reportScreen();checkDeployment()});
